insert into schools (id, ten) values ('pythagoras_vn', 'Pythagoras (bản Việt, biên soạn bởi chủ dự án)') on conflict (id) do nothing;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung_mat', 'tong_quan', '"Tổng quan"'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung_mat', 'tinh_cam', '"Tình cảm"'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung_mat', 'cong_viec', '"Công việc & tiền bạc"'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung_mat', 'bien_co', '"Biến cố & bước ngoặt"'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '1', '{"tong_quan": {"chan_dung": "Người mang số 1 thường được mô tả là người mở đường: đứng trước một khoảng trống, họ thấy chỗ để bắt đầu chứ không thấy rủi ro. Họ học bằng cách tự làm, tự vấp, và tự đứng dậy — ít khi chờ ai cho phép.", "dong_luc": "Được tự quyết và được thấy dấu ấn của chính mình trong việc mình làm.", "diem_manh": ["Quyết nhanh, dám chịu trách nhiệm cho quyết định", "Khởi động được việc mà người khác còn bàn", "Bền bỉ khi đã chọn mục tiêu"], "diem_mu": ["Nghe góp ý như bị thách thức, nên phản ứng trước khi nghe hết", "Coi việc nhờ giúp là yếu, nên ôm việc tới kiệt sức", "Dễ để người bên cạnh ''nhỏ lại'' mà không nhận ra"], "khi_cang_thang": "Siết kiểm soát: tự làm hết, ra quyết định một mình, nói ngắn và cứng hơn thường lệ.", "huong_lon": "Từ ''tôi làm được một mình'' sang ''tôi dẫn được người khác cùng làm'' — sức mạnh thật là để người khác cũng lớn lên."}, "tinh_cam": {"cach_yeu": "Yêu bằng hành động: che chở, lo liệu, đưa ra phương án. Thích chủ động từ lúc tìm hiểu đến lúc quyết định gắn bó.", "can_duoc": "Được tôn trọng quyết định, được ghi nhận công sức, và có khoảng riêng mà không bị coi là lạnh nhạt.", "diem_mu": "Dễ quyết thay cho cả hai; coi cảm xúc của người kia là ''vấn đề cần giải quyết'' thay vì điều cần lắng nghe.", "hop_kieu_nguoi": "Người có chính kiến riêng, đủ vững để nói ''không'' với họ mà vẫn ở lại.", "dau_hieu_lech": "Khi người kia ngày càng ít nói ý mình, chỉ còn ''tuỳ anh/tuỳ em'' — đó là dấu hiệu số 1 đang lấn át.", "hon_nhan": "Thường nhận vai trụ cột, lo phần lớn quyết định lớn; cần tập bàn trước khi quyết, nhất là chuyện tiền và nơi ở."}, "cong_viec": {"the_manh": "Khởi xướng, dẫn đầu, làm việc độc lập, chịu được áp lực quyết định.", "moi_truong": "Nơi được giao quyền, đo bằng kết quả, ít thủ tục chờ duyệt.", "vai_tro": "Người khởi động dự án, trưởng nhóm, người tự kinh doanh.", "nghe": ["Khởi nghiệp, kinh doanh riêng", "Quản lý dự án", "Bán hàng, phát triển thị trường", "Kỹ sư, kiến trúc sư thiết kế giải pháp mới", "Thể thao, huấn luyện"], "cai_bay": "Khởi động nhiều, giao lại ít; khó làm dưới quyền người mình không phục.", "tien_bac": "Dám đầu tư cho ý tưởng của mình; dễ chi mạnh tay vì tin vào phán đoán — cần một người hoặc một quy tắc để phản biện trước khi xuống tiền lớn."}, "bien_co": {"kieu_bien_co": "Những bước ngoặt hay được kể lại thường là lúc phải tự đứng một mình: rời nhà sớm, mất chỗ dựa, bị đẩy vào vai người quyết định khi chưa sẵn sàng.", "bai_hoc": "Độc lập không có nghĩa là cô lập.", "cach_di_qua": "Khi đời đặt bạn vào thế phải tự quyết, hãy quyết — nhưng kể cho ít nhất một người tin cậy nghe trước khi làm."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '2', '{"tong_quan": {"chan_dung": "Số 2 thường được mô tả là người cảm được không khí trước khi ai nói ra. Họ là chất keo của nhóm: hoà giải, kết nối, giữ cho mọi người còn ngồi được với nhau.", "dong_luc": "Được ở trong những mối quan hệ êm ấm, có qua có lại và được người khác cần đến.", "diem_manh": ["Lắng nghe sâu, đọc được cảm xúc người khác", "Khéo hợp tác, làm việc nhóm bền", "Kiên nhẫn, chịu được nhịp chậm"], "diem_mu": ["Né xung đột đến mức để chuyện nhỏ thành chuyện lớn", "Nói ''có'' khi muốn nói ''không''", "Lấy phản ứng người khác làm thước đo giá trị bản thân"], "khi_cang_thang": "Thu mình, im lặng, tự trách; dễ ôm tổn thương mà không nói ra.", "huong_lon": "Từ ''giữ hoà khí bằng mọi giá'' sang ''nói thật một cách tử tế'' — hoà hợp thật cần cả tiếng nói của mình."}, "tinh_cam": {"cach_yeu": "Yêu bằng sự chú tâm: nhớ chi tiết nhỏ, chăm lo cảm xúc, ở bên lặng lẽ.", "can_duoc": "Được chắc chắn rằng mình được yêu — qua lời nói, sự có mặt, sự nhất quán.", "diem_mu": "Dễ hoà tan vào người kia, quên mình muốn gì; giận mà không nói, rồi tổn thương âm ỉ.", "hop_kieu_nguoi": "Người ấm áp, nói rõ ràng, chủ động hỏi han mà không cần được đoán ý.", "dau_hieu_lech": "Khi số 2 bắt đầu ''thôi kệ'' và không còn kể chuyện của mình — khoảng cách đang lớn dần.", "hon_nhan": "Coi trọng sự gắn bó và êm ấm gia đình; cần tập đặt ranh giới với gia đình hai bên."}, "cong_viec": {"the_manh": "Phối hợp, hỗ trợ, đàm phán mềm, chăm sóc khách hàng, làm việc tỉ mỉ.", "moi_truong": "Nhóm hoà thuận, có người dẫn dắt rõ ràng, được ghi nhận đóng góp thầm lặng.", "vai_tro": "Cánh tay phải, người điều phối, người kết nối các bên.", "nghe": ["Nhân sự, tư vấn tâm lý", "Ngoại giao, đàm phán", "Trợ lý điều hành", "Chăm sóc khách hàng", "Âm nhạc, nghệ thuật cần sự tinh tế"], "cai_bay": "Làm nhiều nhưng không lên tiếng nhận phần mình; bị giao việc ''không tên'' quá sức.", "tien_bac": "Thận trọng, thích sự an toàn; dễ cho mượn vì nể — cần một con số giới hạn rõ trước khi giúp ai."}, "bien_co": {"kieu_bien_co": "Bước ngoặt hay đến qua quan hệ: một cuộc chia tay, một lần bị phụ lòng, hoặc một người xuất hiện đúng lúc làm thay đổi hướng đi.", "bai_hoc": "Nhạy cảm là món quà khi đi kèm ranh giới.", "cach_di_qua": "Khi mối quan hệ chao đảo, hãy hỏi ''mình cần gì?'' trước khi hỏi ''người kia nghĩ gì?''."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '3', '{"tong_quan": {"chan_dung": "Số 3 thường được mô tả là người mang niềm vui và ngôn từ: kể chuyện cuốn, nghĩ ra ý tưởng nhanh, làm không khí sáng lên. Bên dưới vẻ vô tư thường là một tâm hồn nhạy và dễ tự hoài nghi.", "dong_luc": "Được thể hiện bản thân và được người khác đón nhận điều mình tạo ra.", "diem_manh": ["Diễn đạt, thuyết phục, truyền cảm hứng", "Sáng tạo, nhiều ý tưởng", "Lạc quan, dễ kết nối"], "diem_mu": ["Bắt đầu nhiều, hoàn thành ít khi hết hứng", "Dùng câu đùa để né chuyện nghiêm túc", "Phân tán năng lượng vào quá nhiều thứ"], "khi_cang_thang": "Nói nhiều hơn, vui gượng, hoặc ngược lại im hẳn và tự chỉ trích.", "huong_lon": "Từ ''nhiều ý tưởng'' sang ''một tác phẩm hoàn chỉnh'' — kỷ luật là thứ biến tài năng thành giá trị."}, "tinh_cam": {"cach_yeu": "Yêu bằng niềm vui, lời nói, những bất ngờ nhỏ; thích mối quan hệ có tiếng cười.", "can_duoc": "Được khen, được nghe, được là chính mình mà không bị chê ''trẻ con''.", "diem_mu": "Né những cuộc nói chuyện khó bằng cách đổi chủ đề; dễ chán khi quan hệ vào giai đoạn đều đều.", "hop_kieu_nguoi": "Người biết thưởng thức sự hài hước của họ nhưng đủ vững để kéo về chuyện thật khi cần.", "dau_hieu_lech": "Khi số 3 chỉ còn đùa mà không còn kể chuyện thật lòng — họ đang tránh một điều gì đó.", "hon_nhan": "Mang không khí vui vào nhà; cần thống nhất trách nhiệm cụ thể để việc nhà, tiền bạc không trôi."}, "cong_viec": {"the_manh": "Giao tiếp, viết, trình bày, sáng tạo nội dung, làm việc với con người.", "moi_truong": "Năng động, có chỗ cho ý tưởng mới, không quá nặng quy trình.", "vai_tro": "Người truyền thông, người lên ý tưởng, gương mặt đại diện.", "nghe": ["Truyền thông, marketing, sáng tạo nội dung", "Viết, báo chí, biên kịch", "Giảng dạy, đào tạo", "Nghệ thuật biểu diễn, thiết kế", "Bán hàng tư vấn"], "cai_bay": "Ôm nhiều dự án dở dang; dễ chán việc lặp lại dù việc đó cần cho thành công.", "tien_bac": "Chi tiêu theo cảm hứng, hào phóng với bạn bè; cần hệ thống tự động (tiết kiệm trước, tiêu sau)."}, "bien_co": {"kieu_bien_co": "Bước ngoặt thường đến khi buộc phải chọn một hướng duy nhất, hoặc sau một lần tài năng bị đánh giá thấp khiến họ phải tự chứng minh.", "bai_hoc": "Tài năng cần một nơi để đổ vào đến cùng.", "cach_di_qua": "Chọn một việc, đặt hạn chót công khai, và hoàn thành nó trước khi mở việc mới."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '4', '{"tong_quan": {"chan_dung": "Số 4 thường được mô tả là người xây nền: kỷ luật, đáng tin, làm từng bước chắc chắn. Họ không ồn ào, nhưng khi họ nói ''được'' thì việc sẽ xong.", "dong_luc": "Sự ổn định, trật tự và cảm giác mình đang xây một thứ bền lâu.", "diem_manh": ["Chăm chỉ, kiên trì, giữ lời", "Có hệ thống, làm việc chi tiết", "Thực tế, biết lường rủi ro"], "diem_mu": ["Cứng nhắc khi kế hoạch thay đổi", "Khó chấp nhận cách làm khác cách mình", "Làm việc quá sức vì nghĩ nghỉ ngơi là lười"], "khi_cang_thang": "Bám chặt quy tắc, khó tính, càu nhàu; làm thêm việc thay vì nói ra mình mệt.", "huong_lon": "Từ ''đúng quy trình'' sang ''linh hoạt mà vẫn vững'' — nền tốt là nền chịu được thay đổi."}, "tinh_cam": {"cach_yeu": "Yêu bằng sự có mặt bền bỉ: giữ lời hứa, lo chuyện thực tế, xây kế hoạch chung.", "can_duoc": "Sự chung thuỷ, nhất quán và cảm giác an toàn — không thích bất ngờ lớn.", "diem_mu": "Thể hiện tình cảm khô khan; nghĩ ''làm cho'' là đủ mà quên ''nói cho''.", "hop_kieu_nguoi": "Người trân trọng sự ổn định nhưng mang thêm chút ấm áp và nhẹ nhõm.", "dau_hieu_lech": "Khi quan hệ chỉ còn lịch trình và bổn phận, không còn thời gian vui chung.", "hon_nhan": "Trụ cột vững về tài chính và nề nếp; cần chủ động dành thời gian lãng mạn như một ''việc phải làm''."}, "cong_viec": {"the_manh": "Tổ chức, vận hành, làm việc chính xác, quản lý quy trình và con số.", "moi_truong": "Có cấu trúc rõ, mục tiêu đo được, được tin giao trách nhiệm lâu dài.", "vai_tro": "Người vận hành, người giữ chất lượng, quản lý tầng giữa.", "nghe": ["Kế toán, kiểm toán, tài chính", "Kỹ thuật, xây dựng", "Quản lý vận hành, chuỗi cung ứng", "Lập trình, phân tích dữ liệu", "Luật, hành chính"], "cai_bay": "Làm tốt việc được giao nhưng ngại nhận việc mới chưa rõ cách làm; dễ bị bỏ lại khi ngành thay đổi.", "tien_bac": "Tiết kiệm, tích luỹ đều; cần cho phép mình chi cho trải nghiệm và học cái mới."}, "bien_co": {"kieu_bien_co": "Bước ngoặt hay là những lúc nền tảng bị lung lay: mất việc ổn định, thay đổi chính sách, kế hoạch dài hạn phải làm lại từ đầu.", "bai_hoc": "An toàn thật đến từ khả năng thích nghi, không từ việc mọi thứ đứng yên.", "cach_di_qua": "Khi kế hoạch đổ, hãy chia việc làm lại thành các bước nhỏ nhất có thể làm trong tuần này."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '5', '{"tong_quan": {"chan_dung": "Số 5 thường được mô tả là người của tự do và trải nghiệm: tò mò, thích đi, thích thử, thích nhịp sống có biến động. Họ học bằng cách sống nhiều cuộc đời trong một đời.", "dong_luc": "Tự do lựa chọn và cảm giác đời mình đang chuyển động.", "diem_manh": ["Thích nghi nhanh với hoàn cảnh mới", "Giao tiếp linh hoạt, thuyết phục", "Dám thử, dám thay đổi"], "diem_mu": ["Khó cam kết lâu dài", "Bốc đồng khi chán", "Dễ sa đà vào những thứ đem lại cảm giác mạnh"], "khi_cang_thang": "Muốn bỏ đi, đổi việc, đổi chỗ — chạy khỏi cảm giác bị giam.", "huong_lon": "Từ ''tự do khỏi mọi ràng buộc'' sang ''tự do chọn điều đáng gắn bó'' — cam kết đúng chỗ cũng là một kiểu tự do."}, "tinh_cam": {"cach_yeu": "Yêu bằng trải nghiệm chung: đi đây đi đó, thử điều mới, những cuộc nói chuyện thú vị.", "can_duoc": "Không gian riêng, sự tin tưởng, và một mối quan hệ không đơn điệu.", "diem_mu": "Dễ chán khi mọi thứ ổn định; nhầm sự an toàn với sự nhàm chán.", "hop_kieu_nguoi": "Người độc lập, có đời sống riêng phong phú, không giữ chặt.", "dau_hieu_lech": "Khi số 5 bắt đầu tìm cảm giác mới ở ngoài mối quan hệ — cần nói ra nhu cầu đổi mới trước khi muộn.", "hon_nhan": "Cần một hôn nhân có ''cửa sổ'': mỗi người có khoảng riêng và hai người có những chuyến đi chung định kỳ."}, "cong_viec": {"the_manh": "Bán hàng, truyền thông, đàm phán, xử lý tình huống, làm việc đa nhiệm.", "moi_truong": "Thay đổi liên tục, đi lại nhiều, được gặp người mới, tự chủ thời gian.", "vai_tro": "Người mở thị trường, người xử lý khủng hoảng, người kết nối đa ngành.", "nghe": ["Du lịch, khách sạn, hàng không", "Bán hàng, phát triển kinh doanh", "Báo chí, truyền thông", "Sự kiện, giải trí", "Tự do (freelance), kinh doanh online"], "cai_bay": "Nhảy việc khi vừa hết cảm giác mới, nên khó tích luỹ chiều sâu và vị trí.", "tien_bac": "Kiếm nhanh, tiêu nhanh; dễ bị hấp dẫn bởi cơ hội ''làm giàu nhanh'' — cần một khoản không đụng tới."}, "bien_co": {"kieu_bien_co": "Đời số 5 thường nhiều bước ngoặt: chuyển nơi sống, đổi nghề, những quyết định bất ngờ — có khi tự chọn, có khi hoàn cảnh đẩy tới.", "bai_hoc": "Thay đổi chỉ có giá trị khi mình học được điều gì từ nó.", "cach_di_qua": "Trước mỗi thay đổi lớn, viết ra: ''mình đang chạy tới điều gì, hay chạy khỏi điều gì?''."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '6', '{"tong_quan": {"chan_dung": "Số 6 thường được mô tả là người của trách nhiệm và chăm sóc: gia đình, bạn bè, cộng đồng tìm đến họ khi cần. Họ có con mắt thẩm mỹ và khao khát làm mọi thứ xung quanh trở nên hài hoà.", "dong_luc": "Được yêu thương, được cần đến và thấy những người mình lo đều ổn.", "diem_manh": ["Tận tâm, có trách nhiệm", "Ấm áp, biết chăm sóc", "Có gu thẩm mỹ, biết tạo không gian dễ chịu"], "diem_mu": ["Lo thay, quyết thay cho người khác", "Hy sinh rồi mong được đền đáp", "Cầu toàn, khó chấp nhận sự không hoàn hảo"], "khi_cang_thang": "Lo âu, kiểm soát, nhắc nhở nhiều; dễ thấy mình là người duy nhất gánh mọi thứ.", "huong_lon": "Từ ''chăm cho mọi người'' sang ''chăm cả chính mình'' — người kiệt sức không chăm được ai lâu."}, "tinh_cam": {"cach_yeu": "Yêu bằng sự chăm lo: nấu ăn, nhắc nhở, lo chuyện nhà, hướng về tương lai chung.", "can_duoc": "Được ghi nhận, được trân trọng những điều mình làm, và một mái nhà ấm.", "diem_mu": "Dễ biến tình yêu thành bổn phận và sự quản lý; khó chấp nhận người kia khác ý mình.", "hop_kieu_nguoi": "Người biết nói lời cảm ơn, có trách nhiệm và cùng chia việc nhà.", "dau_hieu_lech": "Khi số 6 bắt đầu kể công hoặc thấy mình ''bị coi như người giúp việc'' — cần nói ra trước khi oán giận.", "hon_nhan": "Thường coi gia đình là trung tâm đời mình; cần giữ một phần đời riêng ngoài vai vợ/chồng, cha/mẹ."}, "cong_viec": {"the_manh": "Chăm sóc, giáo dục, tư vấn, thẩm mỹ, xây dựng cộng đồng.", "moi_truong": "Có giá trị nhân văn, quan hệ con người tốt, được thấy mình giúp ích.", "vai_tro": "Người cố vấn, người giữ văn hoá nhóm, người lo cho đội.", "nghe": ["Giáo dục, mầm non", "Y tế, chăm sóc sức khoẻ, điều dưỡng", "Tư vấn, công tác xã hội", "Thiết kế nội thất, thời trang, làm đẹp", "Ẩm thực, nhà hàng"], "cai_bay": "Gánh việc của người khác, khó từ chối; làm nhiều nhưng ngại đòi quyền lợi.", "tien_bac": "Chi nhiều cho gia đình và người thân; cần quỹ riêng cho bản thân và tuổi già."}, "bien_co": {"kieu_bien_co": "Bước ngoặt hay gắn với gia đình: lập gia đình, có con, chăm cha mẹ, hoặc một lần phải chọn giữa trách nhiệm và ước mơ riêng.", "bai_hoc": "Yêu thương không có nghĩa là gánh hết.", "cach_di_qua": "Khi gánh nặng gia đình dồn lên, hãy chia việc thành tên từng người — và tự đưa tên mình vào danh sách được chăm."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '7', '{"tong_quan": {"chan_dung": "Số 7 thường được mô tả là người tìm chân lý: thích đào sâu, hỏi ''tại sao'', cần thời gian một mình để nghĩ. Họ có vẻ xa cách nhưng bên trong là một thế giới phong phú.", "dong_luc": "Hiểu tận gốc mọi thứ và tìm ra ý nghĩa thật phía sau bề mặt.", "diem_manh": ["Phân tích sắc, tư duy độc lập", "Trực giác tốt, nhìn ra điều người khác bỏ sót", "Tập trung sâu, chuyên môn cao"], "diem_mu": ["Khép kín, khó chia sẻ cảm xúc", "Hoài nghi, khó tin người", "Dễ nghĩ quá nhiều mà làm quá ít"], "khi_cang_thang": "Rút vào trong, im lặng kéo dài, trở nên châm biếm hoặc lạnh lùng.", "huong_lon": "Từ ''hiểu một mình'' sang ''chia sẻ điều mình hiểu'' — trí tuệ có giá trị khi có người nhận."}, "tinh_cam": {"cach_yeu": "Yêu chậm và sâu; thể hiện qua những cuộc trò chuyện thật lòng hơn là lời ngọt.", "can_duoc": "Sự tôn trọng khoảng lặng, một người hiểu mà không cần giải thích nhiều.", "diem_mu": "Khó mở lòng, để người kia đoán; dễ rút lui khi bị đòi hỏi cảm xúc nhiều.", "hop_kieu_nguoi": "Người sâu sắc, tôn trọng sự riêng tư và đủ kiên nhẫn chờ họ mở lòng.", "dau_hieu_lech": "Khi số 7 ngày càng sống song song — có mặt nhưng không chia sẻ.", "hon_nhan": "Cần một hôn nhân có không gian riêng; nên hẹn những buổi nói chuyện định kỳ để không thành hai người xa lạ."}, "cong_viec": {"the_manh": "Nghiên cứu, phân tích, chuyên môn sâu, giải quyết vấn đề phức tạp.", "moi_truong": "Yên tĩnh, coi trọng chất lượng, cho thời gian suy nghĩ, ít họp hành vô ích.", "vai_tro": "Chuyên gia, người nghiên cứu, cố vấn chiến lược.", "nghe": ["Nghiên cứu khoa học, học thuật", "Công nghệ, phân tích dữ liệu", "Y dược, kỹ thuật chuyên sâu", "Tâm lý học, triết học", "Viết chuyên đề, biên tập"], "cai_bay": "Giỏi nhưng không ai biết vì ngại tự giới thiệu; dễ cầu toàn đến chậm tiến độ.", "tien_bac": "Thận trọng, đầu tư khi đã hiểu kỹ; đôi khi xem nhẹ tiền bạc vì thấy nó không quan trọng bằng tri thức."}, "bien_co": {"kieu_bien_co": "Bước ngoặt thường đến từ bên trong: một khủng hoảng niềm tin, một lần mất đi điều tưởng chắc chắn, buộc họ tìm lại ý nghĩa sống.", "bai_hoc": "Có những câu hỏi không có lời giải, chỉ có cách sống cùng.", "cach_di_qua": "Khi mọi thứ đổ vỡ, cho mình thời gian lặng — nhưng đặt hạn để quay lại kết nối với người khác."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '8', '{"tong_quan": {"chan_dung": "Số 8 thường được mô tả là người của thành tựu và quyền lực thực tế: nhìn ra cơ hội, biết tổ chức nguồn lực, muốn kết quả đo đếm được. Họ có uy, và đời thường thử thách họ bằng chính tiền bạc và quyền hạn.", "dong_luc": "Thành công cụ thể, sự công nhận và khả năng tự chủ tài chính.", "diem_manh": ["Tầm nhìn kinh doanh, nắm bắt cơ hội", "Quản lý nguồn lực, ra quyết định lớn", "Bản lĩnh, chịu áp lực tốt"], "diem_mu": ["Đo giá trị bằng thành tích, kể cả giá trị bản thân", "Cứng rắn quá mức, ít bộc lộ yếu đuối", "Dễ cuốn vào công việc, bỏ quên quan hệ"], "khi_cang_thang": "Kiểm soát chặt, nóng nảy, làm việc nhiều hơn nữa để lấy lại cảm giác nắm quyền.", "huong_lon": "Từ ''quyền lực để có'' sang ''quyền lực để cho'' — thành công bền khi nâng được người khác."}, "tinh_cam": {"cach_yeu": "Yêu bằng sự bảo bọc và cung cấp: lo đời sống vật chất, xây tương lai chắc chắn.", "can_duoc": "Được tôn trọng, được tin vào năng lực, có người cùng chí hướng với tham vọng ấy.", "diem_mu": "Dễ coi tiền và quà là đủ thay lời yêu thương; khó nói ''anh/em cần em/anh''.", "hop_kieu_nguoi": "Người tự tin, có sự nghiệp riêng, không bị lấn át bởi cá tính mạnh.", "dau_hieu_lech": "Khi mọi cuộc nói chuyện chỉ còn công việc và tiền — hoặc khi có tranh giành ai quyết.", "hon_nhan": "Thường xây được nền vật chất vững; cần thoả thuận rõ chuyện tài chính chung – riêng ngay từ đầu."}, "cong_viec": {"the_manh": "Kinh doanh, quản trị, tài chính, đàm phán lớn, xây dựng tổ chức.", "moi_truong": "Có cơ hội thăng tiến, thưởng theo kết quả, quy mô đủ lớn để phát huy.", "vai_tro": "Người điều hành, chủ doanh nghiệp, người ra quyết định đầu tư.", "nghe": ["Quản trị doanh nghiệp", "Tài chính, ngân hàng, đầu tư", "Bất động sản", "Luật kinh doanh", "Quản lý cấp cao"], "cai_bay": "Mạo hiểm quá tay khi tự tin; đặt kết quả trên con người khiến đội kiệt sức.", "tien_bac": "Có khả năng kiếm và quản lý tiền lớn; đời số 8 hay có những lần lên xuống tài chính — cần quỹ dự phòng và người phản biện."}, "bien_co": {"kieu_bien_co": "Bước ngoặt hay xoay quanh tiền, địa vị và quyền hạn: thăng tiến lớn, thất bại kinh doanh, tranh chấp, hoặc lần đứng lên từ con số không.", "bai_hoc": "Giá trị con người không nằm trong bảng cân đối tài sản.", "cach_di_qua": "Khi thất bại, tách ''việc thất bại'' khỏi ''tôi thất bại'' — rồi đếm lại những gì vẫn còn: kỹ năng, quan hệ, sức khoẻ."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '9', '{"tong_quan": {"chan_dung": "Số 9 thường được mô tả là người có tầm nhìn rộng và lòng bao dung: quan tâm tới điều lớn hơn bản thân, dễ đồng cảm, nhiều lý tưởng. Đời họ hay có những lần buông bỏ để bước sang trang mới.", "dong_luc": "Làm điều có ý nghĩa cho người khác và cho thế giới.", "diem_manh": ["Bao dung, đồng cảm sâu", "Tầm nhìn rộng, nghĩ cho số đông", "Có khiếu nghệ thuật và truyền cảm hứng"], "diem_mu": ["Lý tưởng hoá người khác rồi thất vọng", "Cho đi đến mức quên bản thân", "Khó buông quá khứ dù miệng nói đã buông"], "khi_cang_thang": "Xa cách, buồn bã, thấy mình không được hiểu; đôi khi rút lui khỏi mọi thứ.", "huong_lon": "Từ ''cứu thế giới'' sang ''phục vụ trong giới hạn của mình'' — lòng tốt cũng cần biết đủ."}, "tinh_cam": {"cach_yeu": "Yêu rộng lượng, lãng mạn, sẵn sàng tha thứ và hy sinh.", "can_duoc": "Được hiểu những lý tưởng của mình và được yêu cả phần mong manh.", "diem_mu": "Dễ yêu hình ảnh mình tưởng tượng hơn con người thật; ôm nỗi buồn không nói.", "hop_kieu_nguoi": "Người có chiều sâu, có giá trị sống rõ ràng và biết kéo họ về đời thực một cách dịu dàng.", "dau_hieu_lech": "Khi số 9 bắt đầu ''cho đi'' với cả thế giới mà quên người bên cạnh, hoặc âm thầm chuẩn bị rời đi.", "hon_nhan": "Một người bạn đời rộng lượng; cần chú ý những việc đời thường (tiền, nhà cửa) mà họ hay coi là nhỏ."}, "cong_viec": {"the_manh": "Truyền cảm hứng, giảng dạy, nghệ thuật, hoạt động xã hội, nhìn bức tranh lớn.", "moi_truong": "Có sứ mệnh rõ, tác động tới nhiều người, được làm điều mình tin.", "vai_tro": "Người truyền lửa, người cố vấn, người đại diện cho giá trị chung.", "nghe": ["Giáo dục, đào tạo", "Tổ chức phi lợi nhuận, công tác xã hội", "Nghệ thuật, văn chương, điện ảnh", "Y tế, chữa lành", "Ngoại giao, quan hệ quốc tế"], "cai_bay": "Làm việc vì lý tưởng mà quên điều kiện sống; dễ kiệt sức hoặc vỡ mộng.", "tien_bac": "Không đặt nặng tiền, dễ cho đi; cần học rằng có tiền là có thêm khả năng giúp người."}, "bien_co": {"kieu_bien_co": "Đời số 9 nhiều cuộc khép lại: kết thúc một mối quan hệ, rời một nơi, khép một giai đoạn — mỗi lần là một lần học buông.", "bai_hoc": "Kết thúc là một phần của vòng đời, không phải thất bại.", "cach_di_qua": "Khi một chương khép lại, làm một nghi thức nhỏ để chào tạm biệt — rồi mới nhìn sang chương mới."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '11', '{"tong_quan": {"chan_dung": "Số 11 là số cái, thường được mô tả như số 2 tăng cường: trực giác rất nhạy, có khả năng truyền cảm hứng, nhưng cũng mang căng thẳng thần kinh cao. Họ thấy những điều người khác chưa thấy, và đời buộc họ học cách sống với độ nhạy đó.", "dong_luc": "Mang lại ánh sáng, ý nghĩa hoặc niềm tin cho người khác.", "diem_manh": ["Trực giác, cảm nhận sâu sắc", "Truyền cảm hứng, có sức hút tinh thần", "Óc sáng tạo và tầm nhìn"], "diem_mu": ["Lo âu, căng thẳng, dễ quá tải cảm xúc", "Kỳ vọng rất cao vào bản thân rồi tự dằn vặt", "Khó đưa ý tưởng xuống đời thực"], "khi_cang_thang": "Bồn chồn, mất ngủ, dễ xúc động mạnh; có lúc nghi ngờ hoàn toàn chính mình.", "huong_lon": "Từ ''cảm nhận mọi thứ'' sang ''chọn điều để cảm nhận'' — độ nhạy cần được chăm như một nhạc cụ quý."}, "tinh_cam": {"cach_yeu": "Yêu sâu, gắn kết bằng tâm hồn; mong một mối quan hệ có ý nghĩa vượt trên đời thường.", "can_duoc": "Được hiểu mà không bị coi là ''nhạy cảm quá'', được an toàn cảm xúc.", "diem_mu": "Lý tưởng hoá người yêu; dễ tổn thương bởi chi tiết nhỏ và đọc ý quá mức.", "hop_kieu_nguoi": "Người điềm tĩnh, vững vàng, giúp họ ''tiếp đất'' mà không dập tắt lý tưởng.", "dau_hieu_lech": "Khi số 11 im lặng kéo dài hoặc cảm xúc lên xuống thất thường — họ đang quá tải.", "hon_nhan": "Cần nhịp sống gia đình đều đặn để cân bằng thần kinh; nên có thói quen chung giúp thư giãn."}, "cong_viec": {"the_manh": "Truyền cảm hứng, tư vấn, sáng tạo, làm việc cần trực giác và tầm nhìn.", "moi_truong": "Giàu ý nghĩa, ít xung đột gay gắt, tôn trọng sự sáng tạo.", "vai_tro": "Người định hướng tinh thần, người sáng tạo, người chữa lành.", "nghe": ["Tư vấn, trị liệu tâm lý", "Nghệ thuật, âm nhạc, thiết kế", "Giảng dạy, diễn giả", "Truyền thông có sứ mệnh", "Nghiên cứu sáng tạo"], "cai_bay": "Nhiều tầm nhìn nhưng khó triển khai; dễ kiệt sức trong môi trường cạnh tranh gắt.", "tien_bac": "Không giỏi chi tiết tiền bạc; cần một người hoặc công cụ quản lý đều đặn."}, "bien_co": {"kieu_bien_co": "Bước ngoặt thường là những lần ''thức tỉnh'': một trải nghiệm làm đổi hẳn cách nhìn đời, thường đi sau một giai đoạn căng thẳng lớn.", "bai_hoc": "Độ nhạy là món quà khi có nền vững để đứng.", "cach_di_qua": "Trong giai đoạn chao đảo, giữ những thói quen thân thể đơn giản (ngủ, đi bộ, ăn đúng bữa) như mỏ neo."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '22', '{"tong_quan": {"chan_dung": "Số 22 là số cái, thường được gọi là ''người kiến tạo lớn'' — như số 4 mang tầm nhìn của số 11: muốn biến ý tưởng lớn thành công trình thật. Áp lực với chính mình thường rất cao.", "dong_luc": "Xây được điều có giá trị lâu dài cho nhiều người.", "diem_manh": ["Tầm nhìn lớn đi cùng óc thực tế", "Tổ chức, quản lý dự án quy mô", "Kiên định, chịu được áp lực dài hạn"], "diem_mu": ["Áp lực phải làm ''điều lớn'' khiến khó bắt đầu", "Kiểm soát, ôm đồm", "Hy sinh đời sống cá nhân cho công việc"], "khi_cang_thang": "Tê liệt vì kỳ vọng quá cao, hoặc làm việc như cỗ máy, xa cách mọi người.", "huong_lon": "Từ ''phải xây điều vĩ đại'' sang ''xây từng viên gạch tốt'' — công trình lớn là tổng của những ngày bình thường."}, "tinh_cam": {"cach_yeu": "Yêu bằng sự xây dựng: lo nền tảng, kế hoạch dài hạn, che chở bền bỉ.", "can_duoc": "Một người ở bên hiểu tầm vóc mục tiêu của họ và chia sẻ gánh nặng.", "diem_mu": "Đặt công việc lên trước; thể hiện tình cảm ít, nghĩ người kia ''tự hiểu''.", "hop_kieu_nguoi": "Người kiên nhẫn, có đời sống riêng, biết kéo họ về những khoảnh khắc nhỏ.", "dau_hieu_lech": "Khi những dịp quan trọng của gia đình luôn bị ''để sau'' vì việc.", "hon_nhan": "Một trụ cột lớn; cần học nghỉ ngơi và có mặt trọn vẹn trong những khoảnh khắc gia đình."}, "cong_viec": {"the_manh": "Quản lý dự án lớn, kiến trúc hệ thống, xây dựng tổ chức, hoạch định chiến lược.", "moi_truong": "Có tầm ảnh hưởng rộng, dự án dài hơi, được trao nguồn lực.", "vai_tro": "Kiến trúc sư hệ thống, người sáng lập, nhà hoạch định.", "nghe": ["Kiến trúc, quy hoạch, xây dựng", "Quản trị tổ chức lớn", "Kỹ thuật hệ thống", "Chính sách công", "Doanh nghiệp xã hội"], "cai_bay": "Kế hoạch quá lớn so với nguồn lực hiện có; khó tin giao việc.", "tien_bac": "Có khả năng tạo giá trị lớn; nên đi chậm mà chắc, tránh dồn hết vốn vào một dự án."}, "bien_co": {"kieu_bien_co": "Bước ngoặt hay là lúc được trao (hoặc tự nhận) một trách nhiệm lớn vượt tuổi, hoặc một công trình dở dang buộc phải làm lại.", "bai_hoc": "Tầm nhìn lớn cần sự kiên nhẫn lớn.", "cach_di_qua": "Chia mục tiêu lớn thành mốc 90 ngày; ăn mừng từng mốc nhỏ để không kiệt sức."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('chan_dung', '33', '{"tong_quan": {"chan_dung": "Số 33 là số cái hiếm, thường được mô tả như số 6 tăng cường: lòng thương lớn, muốn nâng đỡ và chữa lành người khác. Họ dẫn dắt bằng phục vụ — người ta đi theo vì được họ quan tâm thật lòng.", "dong_luc": "Thấy người khác lớn lên, lành lại nhờ sự nâng đỡ của mình.", "diem_manh": ["Tình thương lớn, kiên nhẫn", "Khả năng nâng đỡ, dạy dỗ, chữa lành", "Trách nhiệm cao với cộng đồng"], "diem_mu": ["Gánh nỗi đau của người khác như của mình", "Hy sinh tới mức quên chăm bản thân", "Đặt kỳ vọng đạo đức quá cao cho mình và người khác"], "khi_cang_thang": "Kiệt sức âm thầm, thấy mình chịu trách nhiệm cho hạnh phúc của tất cả mọi người.", "huong_lon": "Từ ''cứu mọi người'' sang ''giúp người tự đứng lên'' — phục vụ khôn ngoan là phục vụ có giới hạn."}, "tinh_cam": {"cach_yeu": "Yêu hết lòng, bao dung, muốn nâng đỡ người mình yêu.", "can_duoc": "Được chăm sóc lại, được thấy mình không phải lúc nào cũng phải mạnh.", "diem_mu": "Dễ yêu để ''cứu'' người khác; chịu đựng quá mức thay vì đặt giới hạn.", "hop_kieu_nguoi": "Người trưởng thành, tự lo được cho mình, biết chăm lại họ.", "dau_hieu_lech": "Khi số 33 chỉ cho mà không còn nhận, và bắt đầu thấy mệt mỏi với chính tình thương của mình.", "hon_nhan": "Là chỗ dựa tinh thần của cả nhà; cần chia đều trách nhiệm và nhận sự giúp đỡ."}, "cong_viec": {"the_manh": "Giáo dục, chăm sóc, tư vấn, dẫn dắt cộng đồng, nghệ thuật chữa lành.", "moi_truong": "Có giá trị nhân văn, nơi sự tận tâm được trân trọng và trả công xứng đáng.", "vai_tro": "Người thầy, người dẫn dắt cộng đồng, người chữa lành.", "nghe": ["Giáo dục, đào tạo", "Y tế, điều dưỡng, trị liệu", "Công tác xã hội, phi lợi nhuận", "Tư vấn tâm lý, huấn luyện", "Nghệ thuật chữa lành"], "cai_bay": "Làm không công, kiệt sức vì lòng tốt; ngại nói chuyện tiền.", "tien_bac": "Hay dùng tiền giúp người khác; cần quỹ an toàn cho mình trước khi giúp."}, "bien_co": {"kieu_bien_co": "Bước ngoặt thường là những lần phải gánh vác người khác: người thân đau ốm, gia đình khó khăn, hoặc một lần kiệt sức buộc phải học cách nhận giúp đỡ.", "bai_hoc": "Muốn chăm người khác lâu dài, phải chăm mình trước.", "cach_di_qua": "Khi gánh nặng dồn lên, viết ra việc nào thật sự là của mình — và trả lại những việc không phải của mình."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he', 'nguoi_yeu', '{"ten": "Người yêu", "tieu_de": "Hai người, một nhịp yêu", "trong_tam": "Trong tình yêu, điều quan trọng là mỗi người cảm thấy được yêu theo đúng cách mình cần — và hai người nói được với nhau cả điều khó nói.", "cau_hoi_chung": "Tuần này, mỗi người kể cho nhau một điều làm mình thấy được yêu nhất."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he', 'ban_be', '{"ten": "Bạn bè", "tieu_de": "Hai người bạn, hai cách giữ tình bạn", "trong_tam": "Tình bạn bền khi mỗi người được là chính mình, nhịp gặp gỡ hợp cả hai và có lúc thẳng thắn với nhau.", "cau_hoi_chung": "Lần gần nhất hai bạn nói thật với nhau một điều khó nghe là khi nào?"}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he', 'dong_nghiep', '{"ten": "Đồng nghiệp", "tieu_de": "Hai cách làm việc, một mục tiêu", "trong_tam": "Với đồng nghiệp, điều quan trọng là phân vai rõ, hiểu cách người kia làm việc và giao tiếp đúng nhịp của họ — không phải thân nhau.", "cau_hoi_chung": "Trong dự án chung, ai quyết phần nào — hai người đã nói rõ chưa?"}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he', 'sep', '{"ten": "Sếp", "tieu_de": "Làm việc với sếp của bạn", "trong_tam": "Với cấp trên, điều quan trọng là hiểu họ coi trọng điều gì, báo cáo theo cách họ dễ tiếp nhận và giữ được tiếng nói của mình.", "cau_hoi_chung": "Bạn đã hỏi sếp thẳng ''thế nào là làm tốt'' trong vị trí của mình chưa?"}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he', 'gia_dinh', '{"ten": "Gia đình", "tieu_de": "Người thân, hai thế giới trong một mái nhà", "trong_tam": "Trong gia đình, hai người không chọn nhau — điều quan trọng là tôn trọng khác biệt, chia trách nhiệm công bằng và nói ra điều mình cần.", "cau_hoi_chung": "Có điều gì bạn mong người thân này hiểu về mình mà chưa từng nói ra?"}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he_theo_so', '1', '{"nguoi_yeu": {"vai": "Chủ động, thích dẫn nhịp mối quan hệ, thể hiện yêu bằng hành động che chở.", "can": "Được tôn trọng quyết định và có khoảng tự do riêng.", "tranh": "Ra lệnh hay so sánh họ với người khác; chạm vào lòng tự trọng trước mặt người ngoài.", "cach_noi": "Nói thẳng, ngắn, đưa ra lựa chọn thay vì yêu cầu."}, "ban_be": {"vai": "Người rủ rê, khởi xướng kế hoạch, bênh bạn khi cần.", "can": "Người bạn dám theo và dám cãi.", "tranh": "Để họ quyết mọi thứ rồi phàn nàn sau lưng.", "cach_noi": "Góp ý thẳng nhưng riêng tư, không trước đám đông."}, "dong_nghiep": {"vai": "Làm nhanh, thích tự chủ phần việc, hay đề xuất cách mới.", "can": "Phạm vi trách nhiệm rõ và quyền quyết trong phạm vi đó.", "tranh": "Giám sát từng bước hay giành công.", "cach_noi": "Bàn về mục tiêu và kết quả, ít bàn chi tiết thủ tục."}, "sep": {"vai": "Sếp quyết đoán, kỳ vọng tốc độ, thích người chủ động.", "can": "Nhân viên tự giải quyết việc, chỉ báo khi cần quyết.", "tranh": "Mang vấn đề đến mà không có phương án; cãi tay đôi trước tập thể.", "cach_noi": "Báo cáo ngắn: kết quả → vướng gì → đề xuất 2 phương án."}, "gia_dinh": {"vai": "Người đứng mũi chịu sào, hay quyết thay cả nhà.", "can": "Được ghi nhận vai trò và được tin tưởng.", "tranh": "Thách thức uy quyền trực diện lúc căng thẳng.", "cach_noi": "Hỏi ý kiến họ trước, rồi nói nhu cầu của mình rõ ràng."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he_theo_so', '2', '{"nguoi_yeu": {"vai": "Dịu dàng, chu đáo, nhớ những chi tiết nhỏ.", "can": "Sự chắc chắn được yêu qua lời nói và sự có mặt đều đặn.", "tranh": "Im lặng lạnh lùng hay đùa cợt về cảm xúc của họ.", "cach_noi": "Nhẹ nhàng, hỏi han, chủ động hỏi ''em/anh đang nghĩ gì?''."}, "ban_be": {"vai": "Người lắng nghe, người giữ bí mật, người hoà giải trong nhóm.", "can": "Sự quan tâm qua lại, không chỉ khi bạn cần.", "tranh": "Chỉ tìm đến khi có chuyện buồn.", "cach_noi": "Hỏi thăm chuyện của họ, không chỉ kể chuyện mình."}, "dong_nghiep": {"vai": "Phối hợp tốt, hỗ trợ thầm lặng, tỉ mỉ.", "can": "Môi trường hoà nhã và được ghi nhận đóng góp.", "tranh": "Phê bình gay gắt hay giao việc không nói rõ.", "cach_noi": "Ghi nhận trước, góp ý sau, nói riêng."}, "sep": {"vai": "Sếp mềm mỏng, quan tâm đến không khí nhóm, ngại xung đột.", "can": "Nhân viên hợp tác, báo tin xấu sớm nhưng khéo.", "tranh": "Đối đầu công khai; tạo phe nhóm.", "cach_noi": "Trao đổi riêng, đặt vấn đề như ''chúng ta cùng tìm cách''."}, "gia_dinh": {"vai": "Người giữ hoà khí, hay nhường nhịn để nhà yên.", "can": "Được hỏi ý kiến, không bị coi nhường nhịn là hiển nhiên.", "tranh": "Lớn tiếng hay bắt họ chọn phe.", "cach_noi": "Hỏi ''mẹ/bố/anh/chị thấy sao?'' và chờ họ nói hết."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he_theo_so', '3', '{"nguoi_yeu": {"vai": "Vui, lãng mạn, nhiều bất ngờ, giỏi làm người kia cười.", "can": "Được khen, được nghe và mối quan hệ không đơn điệu.", "tranh": "Chê họ trẻ con hay lạnh nhạt với ý tưởng của họ.", "cach_noi": "Hứng thú với chuyện họ kể; nói chuyện nghiêm túc vào lúc thoải mái."}, "ban_be": {"vai": "Linh hồn của buổi gặp, người kể chuyện, người kết nối mọi người.", "can": "Khán giả tán thưởng và bạn cùng vui.", "tranh": "Chỉ xem họ là ''người làm vui'' mà không hỏi chuyện thật.", "cach_noi": "Bắt chuyện bằng câu chuyện; hỏi sâu khi họ đang thư thả."}, "dong_nghiep": {"vai": "Nhiều ý tưởng, giao tiếp tốt, làm không khí nhóm vui.", "can": "Đất cho sáng tạo và được trình bày ý tưởng.", "tranh": "Giao việc lặp lại quá lâu; dập ý tưởng ngay khi mới nói.", "cach_noi": "Nghe hết ý tưởng, rồi cùng chốt việc cụ thể và hạn chót."}, "sep": {"vai": "Sếp truyền cảm hứng, nhiều ý tưởng, đôi khi đổi hướng nhanh.", "can": "Nhân viên biết biến ý tưởng thành việc cụ thể.", "tranh": "Phản bác ý tưởng thẳng thừng trong cuộc họp.", "cach_noi": "Ghi lại ý tưởng, gửi lại tóm tắt việc cần làm để chốt hướng."}, "gia_dinh": {"vai": "Người làm không khí gia đình vui vẻ, hay kể chuyện.", "can": "Được lắng nghe và tán thưởng.", "tranh": "Bỏ qua chuyện họ kể hay chê họ thiếu nghiêm túc.", "cach_noi": "Dùng sự hài hước để mở đầu chuyện khó."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he_theo_so', '4', '{"nguoi_yeu": {"vai": "Chung thuỷ, đáng tin, thể hiện yêu bằng việc làm cụ thể.", "can": "Sự ổn định, nhất quán và kế hoạch rõ ràng.", "tranh": "Thất hứa, thay đổi đột ngột, coi việc làm của họ là hiển nhiên.", "cach_noi": "Cụ thể, rõ ràng; cảm ơn những việc nhỏ họ làm."}, "ban_be": {"vai": "Người bạn đáng tin, có mặt khi cần giúp việc thực tế.", "can": "Đúng hẹn và sự thật thà.", "tranh": "Huỷ hẹn sát giờ, hứa suông.", "cach_noi": "Hẹn cụ thể ngày giờ; nói thật kể cả khi khó nghe."}, "dong_nghiep": {"vai": "Cẩn thận, đúng quy trình, giữ chất lượng.", "can": "Hướng dẫn rõ, thời hạn hợp lý, quy trình nhất quán.", "tranh": "Đổi yêu cầu liên tục, làm ẩu.", "cach_noi": "Đưa số liệu, kế hoạch từng bước; báo trước mọi thay đổi."}, "sep": {"vai": "Sếp kỹ tính, coi trọng quy trình, chất lượng và đúng hạn.", "can": "Nhân viên tin cậy, cẩn thận, báo cáo có số liệu.", "tranh": "Đi đường tắt, trễ hạn không báo.", "cach_noi": "Báo cáo có cấu trúc, đủ chi tiết; xin ý kiến trước khi đổi cách làm."}, "gia_dinh": {"vai": "Trụ cột thực tế, lo nề nếp, tài chính, việc nhà.", "can": "Sự ngăn nắp và trách nhiệm chung.", "tranh": "Coi nhẹ quy tắc nhà, bừa bộn, tiêu xài không kế hoạch.", "cach_noi": "Bàn kế hoạch cụ thể, tránh nói chung chung."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he_theo_so', '5', '{"nguoi_yeu": {"vai": "Cuốn hút, thích phiêu lưu, mang lại cảm giác mới mẻ.", "can": "Tự do, tin tưởng và những trải nghiệm chung.", "tranh": "Kiểm soát, ghen tuông, giữ quá chặt.", "cach_noi": "Rủ cùng làm điều mới; bàn chuyện cam kết bằng lựa chọn, không ràng buộc."}, "ban_be": {"vai": "Người rủ đi chơi, đi xa, thử cái mới.", "can": "Bạn sẵn sàng ''đi luôn'' và không trách khi họ biến mất một thời gian.", "tranh": "Bắt họ theo lịch cố định quá chặt.", "cach_noi": "Ngắn gọn, vui, linh hoạt."}, "dong_nghiep": {"vai": "Linh hoạt, giỏi xử lý tình huống, thích việc đa dạng.", "can": "Sự đa dạng và quyền tự chủ cách làm.", "tranh": "Giao việc đơn điệu, quản lý từng chút.", "cach_noi": "Nói mục tiêu, để họ tự chọn cách; chốt bằng văn bản để không trôi."}, "sep": {"vai": "Sếp năng động, thay đổi nhanh, thích người thích nghi tốt.", "can": "Nhân viên linh hoạt, không ngại việc mới.", "tranh": "Than phiền về thay đổi; cứng nhắc theo kế hoạch cũ.", "cach_noi": "Đưa phương án nhanh; nhắc lại thống nhất bằng tin nhắn ngắn."}, "gia_dinh": {"vai": "Người hay đi, hay đổi, mang chuyện mới về nhà.", "can": "Không bị trói buộc bởi kỳ vọng truyền thống.", "tranh": "Áp đặt, trách móc vì họ khác nếp nhà.", "cach_noi": "Tò mò về trải nghiệm của họ trước khi góp ý."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he_theo_so', '6', '{"nguoi_yeu": {"vai": "Chăm lo, ấm áp, hướng về gia đình và tương lai chung.", "can": "Được trân trọng những việc mình làm và sự cam kết.", "tranh": "Coi sự chăm sóc của họ là đương nhiên; vô trách nhiệm.", "cach_noi": "Cảm ơn cụ thể; nói ra mình muốn tự lo phần nào."}, "ban_be": {"vai": "Người bạn chu đáo, hay giúp, hay khuyên.", "can": "Được ghi nhận và được hỏi thăm lại.", "tranh": "Lợi dụng lòng tốt; gạt phăng lời khuyên.", "cach_noi": "Cảm ơn lời khuyên rồi nói rõ quyết định của mình."}, "dong_nghiep": {"vai": "Tận tâm, lo cho cả nhóm, giữ không khí ấm.", "can": "Môi trường tôn trọng, đối xử công bằng.", "tranh": "Đẩy việc của mình sang cho họ vì biết họ khó từ chối.", "cach_noi": "Nhẹ nhàng, ghi nhận; tự nhận phần việc của mình."}, "sep": {"vai": "Sếp quan tâm đến nhân viên như người nhà, có trách nhiệm cao.", "can": "Nhân viên tận tâm, có tinh thần đội nhóm.", "tranh": "Thờ ơ với tập thể; làm việc chỉ vì mình.", "cach_noi": "Chia sẻ cả khó khăn cá nhân khi ảnh hưởng tới công việc; đề xuất giải pháp chung."}, "gia_dinh": {"vai": "Người chăm lo cả nhà, nhớ mọi dịp, giữ nếp.", "can": "Được giúp đỡ và được cảm ơn.", "tranh": "Để họ gánh hết rồi chê họ hay càm ràm.", "cach_noi": "Nhận việc cụ thể; nói ''để con/em lo phần này''."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he_theo_so', '7', '{"nguoi_yeu": {"vai": "Sâu sắc, kín đáo, yêu chậm và chân thành.", "can": "Khoảng lặng riêng và những cuộc trò chuyện có chiều sâu.", "tranh": "Ép họ bộc lộ cảm xúc ngay; xâm phạm riêng tư.", "cach_noi": "Hỏi những câu mở, chờ họ nghĩ; trò chuyện về ý tưởng và ý nghĩa."}, "ban_be": {"vai": "Bạn ít nhưng chất, cho lời khuyên sắc sảo.", "can": "Sự tôn trọng khi họ cần ở một mình.", "tranh": "Trách họ biến mất; lôi họ vào đám đông ồn ào.", "cach_noi": "Gặp riêng, nói chuyện sâu; nhắn khi cần, không đòi trả lời ngay."}, "dong_nghiep": {"vai": "Chuyên môn sâu, phân tích tốt, thích làm độc lập.", "can": "Thời gian tập trung không bị cắt ngang.", "tranh": "Họp nhiều vô ích; hối thúc khi chưa đủ dữ kiện.", "cach_noi": "Gửi vấn đề bằng văn bản trước, để họ có thời gian nghĩ."}, "sep": {"vai": "Sếp chuyên môn, ít nói, kỳ vọng chất lượng và lập luận chặt.", "can": "Nhân viên có hiểu biết, làm việc kỹ và có căn cứ.", "tranh": "Nói chung chung, thiếu dữ liệu; nịnh bợ.", "cach_noi": "Trình bày lập luận rõ, có dữ liệu; chấp nhận câu hỏi vặn."}, "gia_dinh": {"vai": "Người thân trầm tính, cần không gian riêng trong nhà.", "can": "Được để yên khi cần và được hiểu là không lạnh nhạt.", "tranh": "Coi im lặng của họ là giận dỗi hay vô tâm.", "cach_noi": "Hỏi ngắn, gợi chuyện bằng chủ đề họ quan tâm."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he_theo_so', '8', '{"nguoi_yeu": {"vai": "Mạnh mẽ, bảo bọc, lo cho tương lai vật chất.", "can": "Được tôn trọng năng lực và có người cùng chí hướng.", "tranh": "Chê bai thất bại của họ; tranh quyền công khai.", "cach_noi": "Thẳng thắn, rõ ràng; nói về mục tiêu chung."}, "ban_be": {"vai": "Người bạn có ảnh hưởng, hào phóng, hay giúp kết nối cơ hội.", "can": "Sự tôn trọng và tình bạn không vụ lợi.", "tranh": "Chỉ tìm đến vì cần giúp việc hay tiền.", "cach_noi": "Thẳng, có trọng tâm; ghi nhận thành công của họ."}, "dong_nghiep": {"vai": "Hướng kết quả, quyết đoán, có tham vọng.", "can": "Đồng nghiệp hiệu quả, không lãng phí thời gian.", "tranh": "Chậm trễ không lý do; cạnh tranh ngầm.", "cach_noi": "Đi thẳng vào con số và kết quả."}, "sep": {"vai": "Sếp quyền lực, đòi hỏi cao, nhìn vào kết quả.", "can": "Nhân viên mang lại kết quả đo được.", "tranh": "Viện cớ; thách thức quyền hạn trước mặt người khác.", "cach_noi": "Bắt đầu bằng kết quả và con số; đề xuất có tính toán lợi ích."}, "gia_dinh": {"vai": "Người lo kinh tế, có tiếng nói lớn trong nhà.", "can": "Được tôn trọng và được tin cậy.", "tranh": "Tranh luận về tiền trước mặt người ngoài.", "cach_noi": "Bàn chuyện tiền nong rõ ràng, có kế hoạch."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('quan_he_theo_so', '9', '{"nguoi_yeu": {"vai": "Lãng mạn, bao dung, sống nhiều lý tưởng.", "can": "Được hiểu lý tưởng của mình và yêu cả phần mong manh.", "tranh": "Chế giễu ước mơ của họ; ích kỷ, nhỏ nhen.", "cach_noi": "Nói về ý nghĩa, giá trị; nhẹ nhàng kéo về việc cụ thể."}, "ban_be": {"vai": "Người bạn rộng lượng, giúp không tính toán.", "can": "Sự chân thành và những điều có ý nghĩa cùng làm.", "tranh": "Lợi dụng lòng tốt của họ.", "cach_noi": "Chia sẻ chân thật; rủ cùng làm việc tốt."}, "dong_nghiep": {"vai": "Nhìn bức tranh lớn, truyền cảm hứng, quan tâm tác động xã hội.", "can": "Thấy công việc có ý nghĩa.", "tranh": "Chỉ nói lợi nhuận mà bỏ qua giá trị.", "cach_noi": "Nói ''việc này giúp được ai''; rồi chốt việc cụ thể."}, "sep": {"vai": "Sếp có tầm nhìn, nhân văn, đôi khi xa thực tế.", "can": "Nhân viên chia sẻ giá trị chung và giúp hiện thực hoá.", "tranh": "Coi thường sứ mệnh; chỉ chạy theo chỉ tiêu.", "cach_noi": "Kết nối đề xuất với tầm nhìn chung; đưa kế hoạch thực tế."}, "gia_dinh": {"vai": "Người bao dung, hay lo cho cả họ hàng, cộng đồng.", "can": "Được cảm thông và được chia sẻ gánh nặng.", "tranh": "Trách họ lo chuyện người ngoài hơn người nhà một cách gay gắt.", "cach_noi": "Nói nhẹ nhàng rằng gia đình cũng cần họ."}}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
